//! The runtime protocol as Rust types: the `session` interface of
//! wit/runtime/runtime.wit, written out by hand as a trait and the records
//! it uses. Runtimes inside the workspace implement [`Runtime`] directly
//! (`gp_nes::protocol::NesRuntime` is the first); the WASM component build,
//! with bindings generated by `wit-bindgen`, comes when the first runtime
//! has to load as a component (the model interpreter, Milestone 2).
//!
//! The trait follows the WIT one to one: a method per resource function,
//! with the same names (in snake case) and parameters, and a type per record
//! and variant. `tests/wit.rs` parses the WIT and fails when either side
//! gains, loses or renames something. `load` and the `present` interface
//! aren't mirrored: each runtime loads in its own way, and nothing renders
//! yet.
//!
//! Selectors and run-until conditions share one small grammar, in
//! [`select`]. docs/runtime-protocol.md describes both.

pub mod select;
pub mod wire;

/// The WIT package this crate mirrors.
pub const WIT_PACKAGE: &str = "game-printer:runtime@0.4.0";

/// A selector or model path, such as `ram[0x0770]` or `cpu.pc` ([`select`]).
pub type Path = String;

/// One frame of input. `buttons` holds one byte per controller port, port 1
/// in the low byte; NES bits are A, B, Select, Start, Up, Down, Left, Right
/// from bit 0. `axes` is for sources with analog input. `reset` presses the
/// reset button at the start of the frame, before it runs.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct InputFrame {
    pub buttons: u32,
    pub axes: Vec<i16>,
    pub reset: bool,
}

impl InputFrame {
    /// An input frame with these controller bytes, port 1 first.
    pub fn pads(pads: [u8; 4]) -> Self {
        Self {
            buttons: u32::from_le_bytes(pads),
            axes: Vec::new(),
            reset: false,
        }
    }
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct Rect {
    pub x: i64,
    pub y: i64,
    pub w: u64,
    pub h: u64,
}

/// A value read from a runtime. Game-logic values are integers or
/// fixed-point; floats exist only in the present interface.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Value {
    Int(i64),
    Fixed(i64),
    Flag(bool),
    Text(String),
    Entity(u64),
    Vec2(i64, i64),
}

impl Value {
    /// The value as an integer, for conditions: flags are 0 or 1.
    pub fn as_int(&self) -> Option<i64> {
        match self {
            Self::Int(v) | Self::Fixed(v) => Some(*v),
            Self::Flag(b) => Some(i64::from(*b)),
            Self::Entity(e) => i64::try_from(*e).ok(),
            Self::Text(_) | Self::Vec2(..) => None,
        }
    }
}

impl std::fmt::Display for Value {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Int(v) | Self::Fixed(v) => write!(f, "{v}"),
            Self::Flag(b) => write!(f, "{b}"),
            Self::Text(t) => write!(f, "{t:?}"),
            Self::Entity(e) => write!(f, "entity {e}"),
            Self::Vec2(x, y) => write!(f, "({x}, {y})"),
        }
    }
}

/// A value and the path it was read from.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Entry {
    pub path: Path,
    pub value: Value,
}

/// Something that happened during a step. `frame` is the frame it happened
/// in; `data` holds its fields, such as the scanline or the value written.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Event {
    pub frame: u64,
    pub kind: String,
    pub entity: Option<u64>,
    pub data: Vec<Entry>,
}

/// What `run_until` did: whether the condition held when it stopped, and
/// the events of the frames it ran.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Until {
    pub met: bool,
    pub events: Vec<Event>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PatchResult {
    Applied,
    NeedsReload,
    Rejected(String),
}

/// How `load_state`, or a translation into a model state, took one part of
/// the state.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum LoadHow {
    /// As given.
    Loaded,
    /// Close to what was given; the note's `why` says how.
    Approximated,
    /// Not at all: the runtime, or the mapping, has nothing for it.
    Missing,
}

impl LoadHow {
    pub fn name(self) -> &'static str {
        match self {
            Self::Loaded => "loaded",
            Self::Approximated => "approximated",
            Self::Missing => "missing",
        }
    }
}

/// One part of a loaded state, by model path (or a pattern for many), and
/// why it was taken as it was.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LoadNote {
    pub path: Path,
    pub how: LoadHow,
    pub why: String,
}

/// Features a runtime may support, so tools can degrade gracefully. A set
/// of the WIT `capabilities` flags.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct Capabilities(u16);

impl Capabilities {
    pub const SNAPSHOT: Self = Self(1 << 0);
    pub const FORK: Self = Self(1 << 1);
    pub const PATCH_IN_PLACE: Self = Self(1 << 2);
    pub const PATCH_PARAMETERS: Self = Self(1 << 3);
    pub const FULL_MODEL_QUERY: Self = Self(1 << 4);
    pub const EXPLAIN_MODEL: Self = Self(1 << 5);
    pub const EXPLAIN_CODE: Self = Self(1 << 6);
    pub const EXPLAIN_ORIGINAL: Self = Self(1 << 7);
    pub const PRESENT: Self = Self(1 << 8);
    pub const LOAD_STATE: Self = Self(1 << 9);

    /// Every flag with its WIT name, in the WIT's order.
    pub const ALL: [(&'static str, Self); 10] = [
        ("snapshot", Self::SNAPSHOT),
        ("fork", Self::FORK),
        ("patch-in-place", Self::PATCH_IN_PLACE),
        ("patch-parameters", Self::PATCH_PARAMETERS),
        ("full-model-query", Self::FULL_MODEL_QUERY),
        ("explain-model", Self::EXPLAIN_MODEL),
        ("explain-code", Self::EXPLAIN_CODE),
        ("explain-original", Self::EXPLAIN_ORIGINAL),
        ("present", Self::PRESENT),
        ("load-state", Self::LOAD_STATE),
    ];

    pub const fn empty() -> Self {
        Self(0)
    }

    pub const fn union(self, other: Self) -> Self {
        Self(self.0 | other.0)
    }

    pub const fn contains(self, other: Self) -> bool {
        self.0 & other.0 == other.0
    }

    /// The WIT names of the flags that are set.
    pub fn names(self) -> Vec<&'static str> {
        Self::ALL
            .iter()
            .filter(|(_, flag)| self.contains(*flag))
            .map(|(name, _)| *name)
            .collect()
    }
}

/// The `runtime` resource of the WIT `session` interface. Errors are
/// strings, as in the WIT.
///
/// Inputs are one per frame. Where an operation runs more frames than it was
/// given inputs (`run_until`, `sample`), the last input stays held, and with
/// no inputs at all no buttons are held.
pub trait Runtime: Sized {
    fn capabilities(&self) -> Capabilities;

    // Time. Each input frame advances one fixed tick.

    /// Runs one frame per input frame and returns what happened, in order.
    fn step(&mut self, inputs: &[InputFrame]) -> Result<Vec<Event>, String>;
    /// Runs until `condition` holds, checking before the first frame and
    /// after each one, for at most `max_frames` frames.
    fn run_until(
        &mut self,
        condition: &str,
        inputs: &[InputFrame],
        max_frames: u32,
    ) -> Result<Until, String>;
    /// Frames run since the session started.
    fn frame(&self) -> u64;

    // State. Snapshots and canonical state are opaque to clients; only the
    // runtime that made a snapshot can restore it.

    fn snapshot(&self) -> Vec<u8>;
    fn restore(&mut self, snap: &[u8]) -> Result<(), String>;
    /// An independent copy of the session.
    fn fork(&self) -> Self;
    fn canonical_state(&self) -> Vec<u8>;
    fn state_hash(&self) -> u64;
    /// Loads a canonical model state: another runtime's `canonical_state`
    /// of the same model, or one built from the original's. Returns notes
    /// on the parts it approximated or couldn't load, none when it loaded
    /// all of it. A runtime with no model refuses it.
    fn load_state(&mut self, state: &[u8]) -> Result<Vec<LoadNote>, String>;

    // Observe.

    fn query(&self, selector: &str) -> Result<Vec<Entry>, String>;
    /// Runs `frames` frames and reads every selector after each one: one row
    /// per frame, each row the entries of every selector in order.
    fn sample(
        &mut self,
        selectors: &[String],
        inputs: &[InputFrame],
        frames: u32,
    ) -> Result<Vec<Vec<Entry>>, String>;
    fn entities_at(&self, area: Rect) -> Vec<u64>;

    // Change.

    fn patch(&mut self, model_diff: &str) -> PatchResult;
    fn set(&mut self, p: &str, v: Value) -> Result<(), String>;

    // Explain: the model rule, generated code or original routine behind a value.

    fn explain(&self, p: &str) -> Vec<String>;
}

/// The input for the `i`th frame of a run, holding the last one given past
/// the end, as [`Runtime`] says.
/// A reset is pressed once: holding the last input past the end doesn't
/// repeat it.
pub fn input_at(inputs: &[InputFrame], i: usize) -> InputFrame {
    match inputs.get(i) {
        Some(input) => input.clone(),
        None => InputFrame {
            reset: false,
            ..inputs.last().cloned().unwrap_or_default()
        },
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn capabilities_name_their_flags() {
        let caps = Capabilities::SNAPSHOT.union(Capabilities::FORK);
        assert_eq!(caps.names(), ["snapshot", "fork"]);
        assert!(caps.contains(Capabilities::FORK));
        assert!(!caps.contains(Capabilities::PRESENT));
        assert!(Capabilities::empty().names().is_empty());
    }

    #[test]
    fn inputs_past_the_end_hold_the_last() {
        let a = InputFrame::pads([1, 0, 0, 0]);
        let b = InputFrame::pads([2, 0, 0, 0]);
        let inputs = [a.clone(), b.clone()];
        assert_eq!(input_at(&inputs, 0), a);
        assert_eq!(input_at(&inputs, 1), b);
        assert_eq!(input_at(&inputs, 9), b);
        assert_eq!(input_at(&[], 3), InputFrame::default());
        assert_eq!(InputFrame::pads([0x81, 0x02, 0, 0]).buttons, 0x0281);
    }
}
